package com.doseleaf.app;
import android.app.*;import android.content.*;import android.os.*;import org.json.*;
public class ReminderReceiver extends BroadcastReceiver {
 public void onReceive(Context c,Intent intent){PendingResult result=goAsync();new Thread(()->{try(Database db=new Database(c)){String pid=intent.getStringExtra("pid"),mid=intent.getStringExtra("mid"),time=intent.getStringExtra("time"),date=intent.getStringExtra("date");JSONObject p=db.find(pid);if(p==null)return;JSONArray meds=p.getJSONArray("medicines");JSONObject med=null;for(int i=0;i<meds.length();i++)if(meds.getJSONObject(i).getString("id").equals(mid))med=meds.getJSONObject(i);if(med==null||med.optBoolean("unscheduled"))return;String key=date+"|"+pid+"|"+mid+"|"+time;if(!"taken".equals(db.logs(date).optString(key))){Scheduler.channel(c);NotificationManager nm=c.getSystemService(NotificationManager.class);if(nm.areNotificationsEnabled()){Intent open=new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP);PendingIntent click=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification notification=new Notification.Builder(c,Scheduler.CHANNEL).setSmallIcon(R.drawable.ic_notification).setContentTitle("Doseleaf reminder").setContentText("A scheduled medicine is due. Open to review your prescription.").setVisibility(Notification.VISIBILITY_PRIVATE).setContentIntent(click).setAutoCancel(true).build();nm.notify(key.hashCode(),notification);}}Scheduler.next(c,pid,med,time);}catch(Exception ignored){}finally{result.finish();}}).start();}
}
